module.render:
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sizes = { sm: '0.85em', md: '1em', lg: '1.2em' };
const size = sizes[String(args.size || 'md').toLowerCase()] || '1em';
const color = args.color || 'var(--accent-color)';
const rate = parseFloat(args.rate);
const speaker = parseInt(args.speaker, 10);
const main = sections[0] ? sections[0].trim() : '';
const sub = sections[1] ? sections[1].trim() : '';
const note = sections[2] ? sections[2].trim() : '';
const btn = (kind) => '<button class="mdp-speak-btn" type="button" data-kind="' + kind + '" title="Speak">&#9654;</button>';
let html = '<div class="mdp-mod-speakcard mdp-interactive" style="--speak-color: ' + esc(color) + '; font-size: ' + size + ';"'
  + ' data-highlight="' + (String(args.highlight) === 'false' ? 'false' : 'true') + '"'
  + ' data-mainlang="' + esc(args.mainlang || 'en-US') + '"'
  + ' data-sublang="' + esc(args.sublang || 'ja-JP') + '"'
  + ' data-mainvoice="' + esc(args.mainvoice || '') + '"'
  + ' data-subvoice="' + esc(args.subvoice || '') + '"'
  + ' data-speaker="' + (isNaN(speaker) ? -1 : speaker) + '"'
  + ' data-rate="' + (isNaN(rate) ? '' : rate) + '"'
  + ' data-fallback="' + esc(args.fallback || 'auto') + '"';
// Each line's speaker: engine, voice (above), prompt, the server's options, VOICEVOX shaping.
['main', 'sub'].forEach((k) => {
  ['engine', 'prompt', 'extra', 'pitch', 'intonation', 'volume'].forEach((f) => {
    const v = args[k + f];
    if (v != null && String(v).trim() !== '') html += ' data-' + k + f + '="' + esc(String(v).trim()) + '"';
  });
});
html += '>';
html += '<div class="speakcard-row speakcard-main">' + btn('main') + '<div class="speakcard-text">\n\n' + main + '\n\n</div></div>';
const subspeak = String(args.subspeak) === 'true';
if (sub) {
  html += '<div class="speakcard-row speakcard-sub' + (subspeak ? '' : ' speakcard-nobtn') + '">'
    + (subspeak ? btn('sub') : '')
    + '<div class="speakcard-text">\n\n' + sub + '\n\n</div></div>';
}
if (note) html += '<div class="speakcard-note">\n\n' + note + '\n\n</div>';
html += '</div>';
return '\n\n' + html + '\n\n';

module.script:
export default {
  init(el, ctx) {
    const dbg = function () {
      try {
        if (window.localStorage.getItem('mdpTtsDebug') !== '1') return;
        const a = Array.prototype.slice.call(arguments).join(' ');
        const w = Math.round(el.getBoundingClientRect().width);
        console.log('[mdpTts][speakcard ' + ctx.id + ' ' + ctx.role + ' sync=' + ctx.syncId + ' w=' + w + '] ' + a);
      } catch (e) { /* ignore */ }
    };
    dbg('init');

    // Read-along highlight via the CSS Custom Highlight API — colors a Range
    // without mutating the rendered DOM. One highlight name per window is
    // enough (one utterance plays at a time).
    const HL = 'mdp-speak';
    const canHL = String(el.dataset.highlight) !== 'false'
      && typeof window.Highlight === 'function' && window.CSS && CSS.highlights;
    const clearHL = function () { if (canHL) { try { CSS.highlights.delete(HL); } catch (e) { /* ignore */ } } };
    // Highlight [start, end) measured in textContent characters of `root`.
    const highlightRange = function (root, start, end) {
      if (!canHL || end <= start) return;
      try {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let pos = 0, sNode = null, sOff = 0, eNode = null, eOff = 0, n;
        while ((n = walker.nextNode())) {
          const len = (n.textContent || '').length;
          if (!sNode && start < pos + len) { sNode = n; sOff = start - pos; }
          if (end <= pos + len) { eNode = n; eOff = end - pos; break; }
          pos += len;
        }
        if (!sNode || !eNode) return;
        const range = document.createRange();
        range.setStart(sNode, Math.max(0, sOff));
        range.setEnd(eNode, Math.max(0, eOff));
        CSS.highlights.set(HL, new Highlight(range));
      } catch (e) { /* ignore */ }
    };

    const textElOf = function (kind) {
      const row = el.querySelector(kind === 'main' ? '.speakcard-main' : '.speakcard-sub');
      return row ? row.querySelector('.speakcard-text') : null;
    };
    const btnOf = function (kind) {
      const row = el.querySelector(kind === 'main' ? '.speakcard-main' : '.speakcard-sub');
      return row ? row.querySelector('.mdp-speak-btn') : null;
    };

    // Every surface renders from the shared state:
    //   { playing: 'main'|'sub'|null, prog: {ci,cl}|{f}|null }
    const paint = function (st) {
      st = st || ctx.getShared() || {};
      ['main', 'sub'].forEach(function (kind) {
        const btn = btnOf(kind);
        if (!btn) return;
        const on = st.playing === kind;
        btn.classList.toggle('mdp-speak-playing', on);
        btn.innerHTML = on ? '&#9632;' : '&#9654;';
        // A fallback (the chosen engine could not speak) is told in the tooltip
        // only — nothing on the projected slide changes.
        btn.title = (st.note && st.noteKind === kind) ? 'Speak — ' + st.note : 'Speak';
      });
      if (st.playing && st.prog) {
        const tEl = textElOf(st.playing);
        if (tEl) {
          const full = tEl.textContent || '';
          const text = full.trim();
          const lead = (full.match(/^\s*/) || [''])[0].length;
          const p = st.prog;
          if (typeof p.ci === 'number') {
            let end = (typeof p.cl === 'number' && p.cl > 0) ? p.ci + p.cl : -1;
            if (end < 0) {
              const m = text.slice(p.ci).search(/[\s,.!?;:、。]/);
              end = m > 0 ? p.ci + m : text.length;
            }
            highlightRange(tEl, lead + p.ci, lead + Math.min(end, text.length));
          } else if (typeof p.f === 'number') {
            highlightRange(tEl, lead, lead + Math.round(text.length * p.f));
          }
        }
      } else if (!st.playing) {
        clearHL();
      }
    };
    ctx.onShared(paint);

    // A click on ANY surface only dispatches; the owner performs the speech.
    // NOTE: teardown/re-init runs init() again on the SAME DOM (the module
    // system re-runs scripts without rebuilding the HTML), so listeners MUST
    // be removed on cleanup — otherwise a single physical click fires the
    // stale listener too, which toggles the fresh playback straight off.
    const wired = [];
    el.querySelectorAll('.mdp-speak-btn').forEach(function (btn) {
      const onClick = function (ev) {
        ev.stopPropagation();
        const st = ctx.getShared() || {};
        const kind = btn.dataset.kind;
        dbg('click kind=' + kind + ' playing=' + st.playing);
        if (st.playing === kind) ctx.sendAction('stop');
        else ctx.sendAction('speak', { kind: kind });
      };
      btn.addEventListener('click', onClick);
      wired.push([btn, onClick]);
    });
    ctx.onCleanup(function () {
      wired.forEach(function (p) { p[0].removeEventListener('click', p[1]); });
    });

    if (ctx.role === 'owner') {
      // Utterance ownership lives in a window-global registry keyed by
      // syncId, because the app can run DUPLICATE owner instances of the
      // same card (hidden render surfaces in the main window). With a
      // per-instance `current`, the losing instance's canceled utterance
      // "finishes" → clears the shared playing state and answers the
      // narration's replyTo while the winner is still speaking (symptom:
      // audio plays but ■ flips back, no highlight, narration talks over).
      const REG = window.__mdpSpeakReg || (window.__mdpSpeakReg = {});
      const key = ctx.syncId;
      // The line's speaker as the deck wrote it; the app turns it into speak()
      // options (window.mdpTts.speakerOptions — one mapping for every module).
      const speakerOf = function (kind) {
        const d = el.dataset;
        return {
          engine: d[kind + 'engine'], voice: d[kind + 'voice'], prompt: d[kind + 'prompt'], extra: d[kind + 'extra'],
          pitch: d[kind + 'pitch'], intonation: d[kind + 'intonation'], volume: d[kind + 'volume'],
          lang: d[kind + 'lang'], rate: d.rate, fallback: d.fallback, speaker: d.speaker,
        };
      };
      // Stop whichever instance's utterance is active for this card.
      // answer=true also answers its pending narration reply (explicit
      // stops); play() passes false — the replacement utterance carries
      // the (same) reply instead.
      const stopNow = function (answer) {
        const e = REG[key];
        if (!e) return;
        REG[key] = null;
        dbg('stopNow: stopping current (by=' + e.by + ')');
        e.u.stop();
        if (answer && typeof e.onDone === 'function') e.onDone();
      };
      const play = function (kind, onDone) {
        dbg('play kind=' + kind);
        const tts = window.mdpTts;
        const tEl = textElOf(kind);
        if (!tts || !tEl) { if (typeof onDone === 'function') onDone(); return; }
        stopNow(false);
        const text = (tEl.textContent || '').trim();
        if (!text) { if (typeof onDone === 'function') onDone(); return; }
        const spec = speakerOf(kind);
        // An MDP build without speakerOptions reads the line by its language only.
        const o = typeof tts.speakerOptions === 'function' ? tts.speakerOptions(spec) : { lang: spec.lang };
        o.onProgress = function (p) {
          if (typeof p.charIndex === 'number') ctx.setShared({ prog: { ci: p.charIndex, cl: p.charLength } });
          else if (typeof p.fraction === 'number') ctx.setShared({ prog: { f: p.fraction } });
        };
        // When the chosen engine could not speak, the app says what it did instead.
        o.onEngine = function (info) {
          if (!info.fallback) { ctx.setShared({ note: '', noteKind: null }); return; }
          console.warn('[speakcard] ' + info.message);
          ctx.setShared({ note: info.message || '', noteKind: kind });
        };
        const u = tts.speak(text, o);
        const entry = { u: u, onDone: onDone, by: ctx.id };
        REG[key] = entry;
        ctx.setShared({ playing: kind, prog: null });
        const done = function () {
          // A replaced/canceled utterance is no longer the registry entry:
          // it must neither clear the shared state nor answer the reply.
          if (REG[key] !== entry) { dbg('done: superseded, ignoring'); return; }
          REG[key] = null;
          ctx.setShared({ playing: null, prog: null });
          if (typeof onDone === 'function') onDone();
        };
        u.done.then(done, done);
      };
      ctx.onAction(function (type, payload) {
        dbg('onAction ' + type);
        if (type === 'speak' && payload && payload.kind) play(payload.kind);
        else if (type === 'stop') { stopNow(true); ctx.setShared({ playing: null, prog: null }); }
      });
      // App-wide bus commands (script markers / presenter chips / other
      // modules): `cmd:<tag> play [main|sub]` and `cmd:<tag> stop`. `done`
      // answers the sender's replyTo when the utterance finishes, so an
      // [[emit-wait:]] narration resumes right after the audio.
      ctx.onCommand(function (action, args, done) {
        dbg('onCommand ' + action + ' ' + args.join(' '));
        if (action === 'play' || action === '') play(args[0] === 'sub' ? 'sub' : 'main', done);
        else if (action === 'stop') { stopNow(true); ctx.setShared({ playing: null, prog: null }); done(); }
        else done();
      });
      ctx.onCleanup(function () {
        const mine = REG[key] && REG[key].by === ctx.id;
        dbg('cleanup (owner), hadCurrent=' + mine);
        if (mine) stopNow(true);
        clearHL();
      });
    } else {
      ctx.onCleanup(clearHL);
    }
    paint();
  }
}
